import { cookies } from 'next/headers'
import { toggleNotifications } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get('notifications')?.value === 'on'

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications: {enabled ? 'on' : 'off'}</p>
      <form action={toggleNotifications}>
        <button type="submit">{enabled ? 'Turn off' : 'Turn on'}</button>
      </form>
    </main>
  )
}

'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

const COOKIE = 'notifications'

export async function toggleNotifications() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get(COOKIE)?.value === 'on'
  cookieStore.set(COOKIE, enabled ? 'off' : 'on', { path: '/' })
  refresh()
}
